      unavailablePolicy = activationFailed
        ? { allowed: false, reason: '여행 활성 상태를 확인하지 못했어요.' }
        : { allowed: false, pending: true, reason: '여행 활성 상태를 확인하고 있어요.' };
    } else if (needsReauthentication && !isTripActivated) {
      unavailablePolicy = {
        allowed: false,
        reason: '다시 로그인한 뒤 사용할 수 있습니다',
      };
