        create: unavailablePolicy,
        read: unavailablePolicy,
        update: unavailablePolicy,
        delete: unavailablePolicy,
      };

      return {
        schedule: blockedEntityPolicy,
        expense: blockedEntityPolicy,
        service: SERVICE_POLICIES[policyKey],
      };
